  const resp = item.json || {};
  let j; let aiOutcome;
  if (resp.booking_id && resp.config) {
    j = { ...resp };
    aiOutcome = { error: 'AI node disabled or skipped' };
  } else {
    j = { ...$('AI · Build Draft Request').itemMatching(i).json };
    aiOutcome = extractText(resp);
  }
  let draft = null; let violations = [];
  if (aiOutcome.text) {
    try { draft = JSON.parse(aiOutcome.text); } catch (e) { violations = ['response is not valid JSON']; }
    if (draft) violations = guardrails(draft, j);
  }
  const useAi = draft && violations.length === 0;
  const finalDraft = useAi ? { subject: draft.subject.trim(), body: draft.body.trim() } : buildTemplateDraft(j);
  j.confirmation_subject = finalDraft ? finalDraft.subject : null;
  j.confirmation_body = finalDraft ? finalDraft.body : null;
  j.draft_source = useAi ? `ai (${j.ai_request.provider})` : `template_fallback (${aiOutcome.error || violations.join('; ')})`;
  j.model = useAi ? j.ai_request.model : `template-fallback (configured: ${(j.config || {}).ai_model})`;
  j.draft_guardrail_violations = violations;
  j.draft_status = finalDraft ? 'DRAFT_ONLY · NOT SENT · human approval required' : 'NO_DRAFT';
  j.draft_placeholders = finalDraft ? PLACEHOLDERS.filter((p) => finalDraft.body.includes(p)) : [];
  delete j.ai_request;
  return { json: j, pairedItem: { item: i } };
});

// Assign Booking Owner / Team
// Deterministic routing table + response SLA. Owners are role-based queues (placeholders), not people.

const TEAM_BY_TYPE = {
  client_escalation: { team: 'Client Success · Escalations', owner: 'Account Director (on-call)' },
  product_demo: { team: 'Sales Engineering', owner: 'Solutions Engineer queue' },
  sales_meeting: { team: 'Sales', owner: 'Account Executive queue' },
  consultation: { team: 'Solutions Consulting', owner: 'Consulting queue' },
  onboarding: { team: 'Customer Onboarding', owner: 'Onboarding queue' },
  support_session: { team: 'Support', owner: 'Support queue' },
  quarterly_review: { team: 'Account Management', owner: 'Account Manager queue' },
};

function route(j) {
  switch (j.booking_status) {
    case 'INVALID': return { team: 'Intake Operations', owner: 'Intake review queue' };
    case 'DUPLICATE': return { team: 'Intake Operations', owner: 'No action (linked to original)' };
    case 'CANCELLED': return { team: 'Account Management', owner: 'Account Manager queue' };
    case 'NEEDS_REVIEW':
      if (j.review_reason === 'SECURITY_FLAG') return { team: 'Security Review', owner: 'Security review queue' };
      return { team: 'Scheduling Coordinators', owner: 'Scheduling coordinator queue' };
    case 'NO_AVAILABILITY': {
      const t = TEAM_BY_TYPE[j.meeting_type] || { team: 'Scheduling Coordinators', owner: 'Scheduling coordinator queue' };
      return { ...t, escalation: 'Capacity check with team lead' };
    }
    default:
      return TEAM_BY_TYPE[j.meeting_type] || { team: 'Scheduling Coordinators', owner: 'Scheduling coordinator queue' };
  }
}

return $input.all().map((item, i) => {
  const j = { ...item.json };
  const cfg = j.config || {};
  const r = route(j);
  const slaMin = Number(cfg[`sla_minutes_${String(j.booking_priority || 'NORMAL').toLowerCase()}`]) || 240;
  const received = Date.parse(j.timestamp);
  j.owner = r.owner;
  j.owner_team = r.team;
  j.owner_escalation = r.escalation || null;
  j.sla = {
    priority: j.booking_priority,
    first_response_within_minutes: slaMin,
    respond_by_utc: Number.isFinite(received) ? new Date(received + slaMin * 60000).toISOString().replace('.000Z', 'Z') : null,
  };
  return { json: j, pairedItem: { item: i } };
});

// Build Final Booking Record
// Flattens the pipeline state into one clean record per request, ready for a calendar, CRM,
// scheduling platform or log table. Internal working data (config, availability, rankings) is dropped.
// ---- shared time helpers (inlined by scripts/build-workflow.js) ----
// Pure Intl-based timezone math: no external libraries, DST-safe, deterministic.
const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const MIN = 60 * 1000;

function isValidTimeZone(tz) {
  if (!tz || typeof tz !== 'string') return false;
  // Only accept IANA-style names ("Area/City" or "UTC"); abbreviations like "EST" are ambiguous.
  if (!/^(UTC|Etc\/[A-Za-z0-9+\-]+|[A-Za-z]+\/[A-Za-z0-9_+\-]+(\/[A-Za-z0-9_+\-]+)?)$/.test(tz)) return false;
  try { new Intl.DateTimeFormat('en-US', { timeZone: tz }); return true; } catch (e) { return false; }
}

function zonedParts(utcMs, tz) {
  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone: tz, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit', weekday: 'short',
  });
  const p = {};
  for (const part of dtf.formatToParts(new Date(utcMs))) p[part.type] = part.value;
  return {
    year: +p.year, month: +p.month, day: +p.day, hour: +p.hour % 24, minute: +p.minute, second: +p.second,
    weekday: p.weekday,
    date: `${p.year}-${p.month}-${p.day}`,
    time: `${String(+p.hour % 24).padStart(2, '0')}:${p.minute}`,
  };
}

function tzOffsetMinutes(utcMs, tz) {
  const z = zonedParts(utcMs, tz);
  const asUtc = Date.UTC(z.year, z.month - 1, z.day, z.hour, z.minute, z.second);
  return Math.round((asUtc - Math.floor(utcMs / 1000) * 1000) / MIN);
}

function tzAbbrev(utcMs, tz) {
  const part = new Intl.DateTimeFormat('en-US', { timeZone: tz, timeZoneName: 'short' })
    .formatToParts(new Date(utcMs)).find((x) => x.type === 'timeZoneName');
  return part ? part.value : tz;
}

// Wall-clock date + time in `tz` -> UTC epoch ms. Returns null for invalid or non-existent (DST gap) times.
function zonedToUtc(dateStr, timeStr, tz) {
  const d = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr || '');
  const t = /^(\d{2}):(\d{2})$/.exec(timeStr || '');
  if (!d || !t || !isValidTimeZone(tz)) return null;
  const naive = Date.UTC(+d[1], +d[2] - 1, +d[3], +t[1], +t[2]);
  let utc = naive - tzOffsetMinutes(naive, tz) * MIN;
  const off2 = tzOffsetMinutes(utc, tz);
  utc = naive - off2 * MIN;
  const check = zonedParts(utc, tz);
  if (check.date !== dateStr || check.time !== timeStr) return null; // DST gap or invalid calendar date
  return utc;
}

function toIsoUtc(ms) { return new Date(ms).toISOString().replace('.000Z', 'Z'); }

function localLabel(utcMs, tz) {
  const z = zonedParts(utcMs, tz);
  return `${z.weekday} ${z.day} ${MONTHS[z.month - 1]} ${z.year}, ${z.time}`;
}

function rangeLabel(startMs, endMs, tz) {
  return `${localLabel(startMs, tz)}–${zonedParts(endMs, tz).time} ${tzAbbrev(startMs, tz)} (${tz})`;
}

function minutesOfDay(hhmm) {
  const m = /^(\d{2}):(\d{2})$/.exec(hhmm || '');
  return m ? +m[1] * 60 + +m[2] : null;
}

function addDays(dateStr, n) {
  const [y, m, d] = dateStr.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);
}

function weekdayOf(dateStr) {
  const [y, m, d] = dateStr.split('-').map(Number);
  return WEEKDAYS[new Date(Date.UTC(y, m - 1, d)).getUTCDay()];
}

function dayDiff(a, b) {
  const pa = a.split('-').map(Number); const pb = b.split('-').map(Number);
  return Math.round((Date.UTC(pb[0], pb[1] - 1, pb[2]) - Date.UTC(pa[0], pa[1] - 1, pa[2])) / 86400000);
}

function overlaps(aStart, aEnd, bStart, bEnd) { return aStart < bEnd && bStart < aEnd; }

function slotView(startMs, endMs, requesterTz, businessTz) {
  return {
    start_utc: toIsoUtc(startMs),
    end_utc: toIsoUtc(endMs),
    local: requesterTz && isValidTimeZone(requesterTz) ? rangeLabel(startMs, endMs, requesterTz) : null,
    business: rangeLabel(startMs, endMs, businessTz),
  };
}
// ---- end shared time helpers ----
// ---- shared availability helpers (inlined by scripts/build-workflow.js; requires time-utils) ----
// `av` is the normalized availability object produced by either
// "DEMO · Load Calendar Availability" or "Calendar · Map Free/Busy" (production).

function referenceNow(cfg) {
  if (cfg && cfg.demo_mode && cfg.demo_reference_date) {
    const ms = zonedToUtc(cfg.demo_reference_date, cfg.demo_reference_time || '17:00', cfg.business_timezone);
    if (ms !== null) return ms;
  }
  return Date.now();
}

function isSchedulable(j) {
  return j.request_action === 'book' &&
    j.validation && j.validation.missing_fields.length === 0 && j.validation.invalid_fields.length === 0 &&
    !(j.duplicate && j.duplicate.is_duplicate) &&
    j.timezone_normalization && j.timezone_normalization.status === 'ok';
}

// Evaluate one slot against business rules + calendar. Never mutates inputs.
function checkSlot(startMs, endMs, av, cfg, nowMs) {
  const tz = av.business_timezone;
  const reasons = [];
  const conflicts = [];
  const zs = zonedParts(startMs, tz);
  const date = zs.date;
  const buffer = (Number(cfg.buffer_minutes) || 0) * MIN;
  const noticeMs = (Number(cfg.min_notice_hours) || 0) * 60 * MIN;

  if (startMs < nowMs) reasons.push('start time is in the past');
  else if (startMs < nowMs + noticeMs) reasons.push(`inside the ${cfg.min_notice_hours}h minimum-notice window`);
  if (av.coverage && (date < av.coverage.from || date > av.coverage.to)) reasons.push(`outside calendar data range (${av.coverage.from} to ${av.coverage.to})`);
  if (!av.business_days.includes(weekdayOf(date))) reasons.push(`${weekdayOf(date)} is not a business day`);

  const openMs = zonedToUtc(date, av.business_hours.start, tz);
  const closeMs = zonedToUtc(date, av.business_hours.end, tz);
  if (openMs === null || closeMs === null || startMs < openMs || endMs > closeMs) {
    reasons.push(`outside business hours (${av.business_hours.start}–${av.business_hours.end} ${tz})`);
  }
  for (const b of av.recurring_blocks || []) {
    if (!b.days.includes(weekdayOf(date))) continue;
    const bs = zonedToUtc(date, b.start, tz); const be = zonedToUtc(date, b.end, tz);
    if (bs !== null && be !== null && overlaps(startMs, endMs, bs, be)) reasons.push(`overlaps ${b.label} ${b.start}–${b.end}`);
  }
  for (const ev of av.busy || []) {
    const es = Date.parse(ev.start_utc); const ee = Date.parse(ev.end_utc);
    if (overlaps(startMs, endMs, es - buffer, ee + buffer)) {
      const direct = overlaps(startMs, endMs, es, ee);
      conflicts.push({
        event_id: ev.id, title: ev.title, kind: ev.kind,
        time_business: rangeLabel(es, ee, tz),
        overlap_type: direct ? 'direct overlap' : `within ${cfg.buffer_minutes}-min buffer`,
      });
    }
  }
  if (conflicts.length) reasons.push(`overlaps existing event${conflicts.length > 1 ? 's' : ''}: ${conflicts.map((c) => `${c.title} (${c.overlap_type})`).join('; ')}`);
  return { ok: reasons.length === 0, reasons, conflicts };
}

// Requester-side sanity: do not propose slots at unreasonable local hours for the requester.
function withinRequesterDay(startMs, endMs, requesterTz, cfg) {
  const s = zonedParts(startMs, requesterTz); const e = zonedParts(endMs, requesterTz);
  const lo = minutesOfDay(cfg.requester_day_start || '08:00'); const hi = minutesOfDay(cfg.requester_day_end || '19:00');
  const sm = minutesOfDay(s.time); const em = minutesOfDay(e.time);
  return s.date === e.date && sm >= lo && em <= hi;
}

function overlapsHeld(startMs, endMs, holds, cfg, ownId) {
  const buffer = (Number(cfg.buffer_minutes) || 0) * MIN;
  return holds.find((h) => h.booking_id !== ownId && overlaps(startMs, endMs, h.start - buffer, h.end + buffer)) || null;
}

// Pick up to `max` ranked candidates with day/spacing diversity, skipping excluded slots.
function pickDiverse(ranked, cfg, isExcluded) {
  const max = Number(cfg.max_candidate_slots) || 3;
  const perDay = Number(cfg.max_candidates_per_day) || 2;
  const spacing = (Number(cfg.min_candidate_spacing_minutes) || 60) * MIN;
  const picked = [];
  for (const c of ranked) {
    if (picked.length >= max) break;
    const s = Date.parse(c.start_utc); const e = Date.parse(c.end_utc);
    if (isExcluded && isExcluded(s, e)) continue;
    const sameDay = picked.filter((p) => p.business_date === c.business_date);
    if (sameDay.length >= perDay) continue;
    if (sameDay.some((p) => Math.abs(Date.parse(p.start_utc) - s) < spacing)) continue;
    picked.push(c);
  }
  return picked;
}
// ---- end shared availability helpers ----
